import DOMPurify from "dompurify";

const FOOTER_HTML =
  'Replies are generated by AI. <a href="/help/ai-replies">Learn more</a>.';

type Reply = { id: string; text: string; html?: string };

export function ReplyCard({ reply }: { reply: Reply }) {
  return (
    <section className="reply-card">
      {reply.html ? (
        <div
          className="reply-rich"
          dangerouslySetInnerHTML={{
            __html: DOMPurify.sanitize(reply.html, {
              FORBID_TAGS: ["img", "style", "form"],
              FORBID_ATTR: ["style", "srcset"],
            }),
          }}
        />
      ) : (
        <p className="reply-text">{reply.text}</p>
      )}
      <footer className="disclaimer" dangerouslySetInnerHTML={{ __html: FOOTER_HTML }} />
    </section>
  );
}
